{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"RSO and JCO no-fault eviction relocation assistance","requirement":"Before evicting tenants from RSO or JCO units for a no-fault reason, a landlord must file a Declaration of Intent to Evict with LAHD and pay relocation assistance within 15 days of serving the termination notice.","key_value":"Eligible tenant $11,000 (under 3 years) or $14,400 (3+ years); qualified tenant $23,150 or $27,400; low income $10,550/$21,250; July 1, 2026–June 30, 2027","coverage_conditions":"All tenant not-at-fault evictions from units covered by the Rent Stabilization Ordinance or the Just Cause Ordinance in the City of Los Angeles; relocation paid per unit.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"RSO/JCO covered residential rental units"},"exemptions":"Exempt: evicting a resident manager to replace with another resident manager; evictions required by hazardous conditions from a natural disaster not caused by landlord negligence. Reduced amounts for mom-and-pop owner/relative/manager occupancy (4 or fewer units) and JCO single-family dwellings owned by natural persons (one month's rent).","penalty":"Failure to file the Landlord Declaration makes the eviction a violation of the RSO or JCO; non-payment may be raised as an affirmative defense in an eviction action.","effective_date":"2026-07-01","citation":"L.A. Mun. Code § 151.09","quoted_span":"All tenant not- at-fault evictions require payment of relocation assistance and the filing of a Declaration of Intent to Evict form with the Los Angeles Housing Department (LAHD) before evicting tenants from units covered by the Rent Stabilization Ordinance (RSO) or the Just Cause Ordinance (JCO).","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Resident Protections Ordinance relocation for demolition for new construction","requirement":"An owner demolishing a Protected Unit for new construction must comply with the RPO's relocation requirements and choose one of three relocation options, paying the highest applicable State or City amount.","key_value":"$250,000 per displaced unit","coverage_conditions":"Protected Units demolished for the purpose of new construction; Protected Units include RSO units, rent-controlled units, lower-income tenancies within the past 5 years, and Ellis Act withdrawals within 10 years.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Protected Units demolished for new construction in the City of Los Angeles"},"exemptions":null,"penalty":"Failure to comply may result in financial penalties starting at $250,000 per displaced unit and withholding of LAHD permit clearances.","effective_date":"2025-02-11","citation":"Los Angeles Ordinance 188481","quoted_span":"Failure to comply with the RPO may result in financial penalties starting at $250,000 per displaced unit and withholding of LAHD permit clearances.","interaction":"Owner must pay the highest of the applicable State (HCA) and City (RSO/JCO) relocation amounts.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Housing Crisis Act relocation for lower income demolition displacees","requirement":"The Housing Crisis Act requires relocation payments, consistent with benefits public entities must pay under Government Code Chapter 16, for lower income households (80% AMI or lower) displaced by demolition where the owner replaces the units with new construction.","key_value":"80% AMI or lower","coverage_conditions":"Lower income households (80% AMI or lower) displaced by demolition of their units where the owner will replace the units with new construction; RSO and JCO amounts must be enhanced for lower income tenants.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Lower income households displaced for demolition with replacement new construction"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Cal. Gov. Code § 66300.6","quoted_span":"The City’s Resident Protections Ordinance (RPO) and the State’s Housing Crisis Act (HCA) require that ONLY lower income households (80% AMI or lower) being displaced for demolition of their units where the owner will replace the units with new construction receive relocation payment consistent to the relocation benefits required to be paid by public entities under Chapter 16","interaction":"HCA requires RSO and JCO amounts be enhanced for lower income tenants regardless of RPO applicability.","confidence":0.7,"conflict_flag":false,"conflict_note":null}
